use super::*;
use app_core::AppError;
use serde_json::json;

/// `tests/fixtures/reference_summaries.json` is generated by running the reference's own
/// `summarize` / `detailFrom` (tools/gen_audit_fixture.mjs), so this is a differential test.
#[test]
fn summaries_match_reference_output() -> Result<(), String> {
    let fixture: Value =
        serde_json::from_str(include_str!("../tests/fixtures/reference_summaries.json")).map_err(|e| e.to_string())?;
    let rows = fixture["summaries"].as_array().ok_or("summaries missing")?;
    assert!(rows.len() >= 200);
    for row in rows {
        let (m, p, expected) = (row[0].as_str(), row[1].as_str(), row[2].as_str());
        let (Some(m), Some(p), Some(expected)) = (m, p, expected) else { return Err(format!("bad row {row}")) };
        assert_eq!(summarize(m, p), expected, "{m} {p}");
    }
    for row in fixture["details"].as_array().ok_or("details missing")? {
        // A numeric result is stored by Postgres in the varchar column as its text form.
        let expected = match &row[1] {
            Value::String(s) => Some(s.clone()),
            Value::Number(n) => Some(n.to_string()),
            _ => None,
        };
        assert_eq!(detail_from(&row[0]), expected, "{}", row[0]);
    }
    Ok(())
}

async fn fresh() -> AppResult<(tempfile::TempDir, Db)> {
    let dir = tempfile::tempdir().map_err(AppError::internal)?;
    let db = Db::open(&dir.path().join("t.db")).await?;
    Ok((dir, db))
}

fn entry(user: &str, name: &str, action: &str) -> NewEntry {
    NewEntry {
        user_id: Some(user.into()),
        username: Some(name.into()),
        action: action.into(),
        method: Some("POST".into()),
        path: Some("/api/x".into()),
        status_code: Some(201),
        detail: None,
    }
}

#[tokio::test]
async fn list_is_newest_first_paginated_and_filterable() -> AppResult<()> {
    let (_d, db) = fresh().await?;
    for i in 0..25 {
        let (u, n) = if i % 2 == 0 { ("u1", "zed") } else { ("u2", "amy") };
        record(&db, entry(u, n, &format!("a{i}"))).await;
    }
    let p1 = list(&db, 1, 20, None).await?;
    assert_eq!((p1.total, p1.page, p1.limit, p1.total_pages, p1.data.len()), (25, 1, 20, 2, 20));
    assert_eq!(p1.data[0].action, "a24");
    let p2 = list(&db, 2, 20, None).await?;
    assert_eq!(p2.data.len(), 5);
    let only_u2 = list(&db, 1, 100, Some("u2")).await?;
    assert_eq!(only_u2.total, 12);
    assert!(only_u2.data.iter().all(|e| e.user_id.as_deref() == Some("u2")));

    let v = serde_json::to_value(&p1).map_err(AppError::internal)?;
    assert_eq!(v["totalPages"], json!(2));
    assert_eq!(v["data"][0]["statusCode"], json!(201));
    assert!(v["data"][0].get("userId").is_some());

    let us = users(&db).await?;
    assert_eq!(us.iter().map(|u| u.username.as_deref()).collect::<Vec<_>>(), vec![Some("amy"), Some("zed")]);
    Ok(())
}

#[test]
fn total_pages_is_ceiling() {
    assert_eq!(Paginated::<()>::new(vec![], 0, 1, 20).total_pages, 0);
    assert_eq!(Paginated::<()>::new(vec![], 20, 1, 20).total_pages, 1);
    assert_eq!(Paginated::<()>::new(vec![], 21, 1, 20).total_pages, 2);
}
